j:jelly.script:
jQuery(".agentgroup_itsm").addClass("hideBlock")
jQuery(".agentgroup_csm").addClass("hideBlock")
jQuery(".agentgroup_hr").addClass("hideBlock")
jQuery("#entitlement_itsm_pro").on("click", function(e) {
	let isAlreadySelected = jQuery("#entitlement_itsm_pro").hasClass("active-card");
	let actualVarId = jQuery(gel("variable_map")).find("item[qname='entitlement_value']").attr("id");
	let actualVarEl = gel("IO:" + actualVarId);
	let value = actualVarEl $[AMP]$[AMP] actualVarEl.value?JSON.parse(actualVarEl.value): {};

	if(isAlreadySelected) {
		if(jQuery("#entitlement_itsm").hasClass("active-card")) {
			jQuery(".agentgroup_itsm").removeClass("hideBlock");
		}else {
			if(!jQuery(".agentgroup_itsm").hasClass("hideBlock")) {
				jQuery(".agentgroup_itsm").addClass("hideBlock");
			}
		}
	}else{
		if(jQuery("#entitlement_itsm").hasClass("active-card")) {
			jQuery("#entitlement_itsm").removeClass("active-card");
			value["ITSM"] = false;
		}
		jQuery(".agentgroup_itsm").removeClass("hideBlock");
	}

	isAlreadySelected?jQuery("#entitlement_itsm_pro").removeClass("active-card"): jQuery("#entitlement_itsm_pro").addClass("active-card")					
	value["ITSM_PRO"] = isAlreadySelected?false: true;
	actualVarEl.value = JSON.stringify(value);
});
